<script module lang="ts">
/**
 * Free-text tags (`design/components/tag-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tag-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  agentMember,
  composingKey,
  holdFieldEscape,
  joinSlot,
  lineStartKey,
  watchEffect,
} from '@polymorph/svelte'
import { useListPresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/tag-input.module.css'
import TagInputChip from './TagInputChip.svelte'

export type TagInputCountLabel = (tags: { count: number; max?: number; atMax: boolean }) => string

export interface TagInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * The count sentence in the host's words, part of the field's description, the localization
   * seam; the default is `{count} added`, or `Maximum of {max} added` at the maximum.
   */
  countLabel?: TagInputCountLabel
  defaultValue?: string[]
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * At the maximum the field is read-only, not removed and not disabled. A full field is still
   * what FormField's label points at, and keyboard users can still reach it. It blocks typing,
   * not access.
   */
  max?: number
  /**
   * Serialises comma-joined into a hidden input, for a native form post.
   */
  name?: string
  /**
   * Fires when focus leaves the whole field, for touched validation. Chips and input are one
   * control, so moving focus between them is not a blur. Only leaving the field is.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (values: string[]) => void
  /**
   * Shown only while empty. The chips are the value, and a placeholder beside them is clutter.
   */
  placeholder?: string
  /**
   * The accessible name of a chip's remove button. It is a function because the tag is data and
   * the text around it comes from the app's message catalog. Defaults to `Remove {tag}`.
   */
  removeLabel?: (tag: string) => string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Normalize or reject: return the tag as it should be stored, or `null` to reject it. A
   * rejection flashes the container and shows no message. Persistent written errors come from
   * FormField.
   */
  validate?: (raw: string) => string | null
  value?: string[]
}

export const controlKind = 'field'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  countLabel = ({ count, max, atMax }: Parameters<TagInputCountLabel>[0]) =>
    atMax ? `Maximum of ${max} added` : `${count} added`,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  max,
  name,
  onBlur,
  onChange,
  placeholder,
  removeLabel = (tag: string) => `Remove ${tag}`,
  size = 'md',
  validate = (raw: string) => (raw.trim() === '' ? null : raw.trim()),
  value,
}: TagInputProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
// svelte-ignore state_referenced_locally
let uncontrolled = $state(defaultValue ?? [])
let draft = $state('')
let flashing = $state(null as string | null)
let refused = $state(false)
let announcement = $state('')
let settled = $state(false)
let chipList = $state<HTMLElement | null>(null)
let field = $state<HTMLElement | null>(null)
const values = $derived(value ?? uncontrolled)
const atMax = $derived(max !== undefined && values.length >= max)
const countId = $derived(`${id ?? uid}-count`)
const commit = $derived((next: string[]) => {
  uncontrolled = next
  onChange?.(next)
})
const add = $derived((raws: string[]) => {
  const next = [...values]
  let refusal = false
  let duplicate: string | null = null
  for (const raw of raws) {
    if (max !== undefined && next.length >= max) break
    const tag = validate(raw)
    if (tag === null) {
      refusal = true
      continue
    }
    if (next.includes(tag)) {
      duplicate = tag
      continue
    }
    next.push(tag)
  }
  refused = refusal
  flashing = duplicate
  if (next.length !== values.length) commit(next)
})
const removeButton = $derived(
  (at: number) =>
    chipList?.querySelectorAll<HTMLElement>(':scope > li:not([data-removing]) button')[at] ?? null,
)
const remove = $derived((tag: string) => {
  const before = values
  const at = before.indexOf(tag)
  const target = at === -1 || at + 1 >= before.length ? null : removeButton(at + 1)
  commit(before.filter((other) => other !== tag))
  announcement = `${tag} removed, ${before.length - 1} remain`
  if (target) target.focus()
  else field?.focus()
})
const receive = $derived((event: Event) => {
  draft = (event.target as HTMLInputElement).value
})
const clearable = $derived(draft !== '')
const fieldKeyDown = $derived((event: KeyboardEvent) => {
  if (composingKey(event)) return
  if (event.key === 'Enter' || event.key === ',') {
    event.preventDefault()
    add([draft])
    draft = ''
    return
  }
  if (event.key === 'Escape' && draft !== '') {
    event.preventDefault()
    draft = ''
    return
  }
  if (event.key === 'Backspace' && draft === '') {
    const last = values[values.length - 1]
    if (last !== undefined) remove(last)
    return
  }
  // The direction is a computed style, read only for an arrow.
  if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return
  const input = event.target as HTMLInputElement
  if (event.key === lineStartKey(chipList ?? input) && input.selectionStart === 0) {
    removeButton(values.length - 1)?.focus()
  }
})
const chipKeyDown = $derived((event: KeyboardEvent, tag: string) => {
  const at = values.indexOf(tag)
  if (at === -1) return
  if (event.key === 'Backspace' || event.key === 'Delete') {
    event.preventDefault()
    remove(tag)
    return
  }
  if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
    event.preventDefault()
    const step = event.key === lineStartKey(chipList ?? (event.target as Element)) ? -1 : 1
    if (at + step === values.length) field?.focus()
    else if (at + step >= 0) removeButton(at + step)?.focus()
  }
})
const receivePaste = $derived((event: ClipboardEvent) => {
  const pasted = event.clipboardData?.getData('text') ?? ''
  if (!/[\n,]+/.test(pasted)) return
  event.preventDefault()
  add(pasted.split(/[\n,]+/))
  draft = ''
})
const pressContainer = $derived((event: MouseEvent) => {
  if ((event.target as HTMLElement).closest('button, input')) return
  event.preventDefault()
  field?.focus()
})
const leave = $derived((event: FocusEvent) => {
  if ((event.currentTarget as HTMLElement).contains(event.relatedTarget as Node | null)) return
  onBlur?.(event)
})
const chips = useListPresence(
  () => values,
  (tag: string) => tag,
)
const effect1 = () => {
  settled = true
}
watchEffect(effect1)
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = clearable && field ? holdFieldEscape(field) : () => {}
  release2 = () => {
    ran()
  }
}
watchEffect(effect2, { watch: () => clearable })
onDestroy(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'TagInput',
    element: () => field,
    state: () => ({ value: values, disabled: disabled, invalid: invalid }),
    actions: {
      add: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (/[\n,]/.test(value)) {
              throw new Error('A tag holds no comma or line break: add each tag on its own.')
            }
            if (atMax) throw new Error(`The field holds its maximum of ${max} tags.`)
            const tag = validate(value)
            if (tag === null) throw new Error(`The field refuses "${value}" as a tag.`)
            if (values.includes(tag)) throw new Error(`The field already holds "${tag}".`)
            add([value])
          })(),
      },
      clear: () =>
        (() => {
          if (values.length > 0) commit([])
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.container}
    data-size={size}
    data-state={(atMax) ? 'at-max' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-refused={(refused) ? '' : undefined}
    data-member="tag-input"
    onmousedown={(event) => { pressContainer(event) }}
    onfocusout={(event) => { leave(event) }}
    onanimationend={() => { ((refused = false), (flashing = null)) }}
    ><ul bind:this={chipList} class={styles.chips}
      >{#each chips.current as chip (chip.key)
        }<TagInputChip
          tag={chip.item}
          open={chip.open}
          appear={settled}
          flash={flashing === chip.item}
          {disabled}
          removeLabel={removeLabel(chip.item)}
          onRemove={() => { remove(chip.item) }}
          onKeyDown={(event) => { chipKeyDown(event, chip.item) }}
          onDone={() => { chip.done() }}
      />{/each
    }</ul
    ><input
      bind:this={field}
      class={styles.input}
      type="text"
      value={draft}
      placeholder={values.length === 0 ? placeholder : undefined}
      readonly={atMax}
      {disabled}
      {id}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={[ariaDescribedby, countId].filter(Boolean).join(' ')}
      aria-required={ariaRequired}
      aria-invalid={(invalid) ? true : undefined}
      oninput={(event) => { receive(event) }}
      onkeydown={(event) => { fieldKeyDown(event) }}
      onpaste={(event) => { receivePaste(event) }}
    /><span class={styles.reader} id={countId}
      >{countLabel({ count: values.length, max, atMax })
    }</span
    ><span class={styles.reader} aria-live="polite">{announcement}</span
    >{#if name !== undefined}<input type="hidden" {name} value={values.join(',')} {disabled} />{/if
  }</div
>{/if
}{@render joined.end?.()}
